describe("local practice", () => {
  it("click and check the effect", () => {
    cy.visit("/practice.html");
    cy.document().then(doc => { const b=doc.createElement("button"); b.textContent="Save"; b.onclick=()=>b.textContent="Done"; doc.body.replaceChildren(b); });
    cy.contains("button", "Save").click();
    cy.contains("button", "Done").should("be.visible");
  });
});
